// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 100 ether);
        vm.deal(address(c), amount);
        vm.prank(address(this));
        bool ok;
        try c.sendMoney(actor, amount, "") {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok || address(c).balance == 0);
    }
}
